test("renamed browser checks preserve every invocation and output destination", () => {
  const release: ReleaseRecord = {
    schemaVersion: 2,
    version: "0.3.0",
    commit: "a".repeat(40),
    sourceTree: "clean",
    packages: releasePackageNames.map((name) => ({ name, version: "0.3.0", filename: archiveFilename({ name, version: "0.3.0" }), sha512: "a".repeat(128), blockers: [] })),
  };
  const root = path.join(os.tmpdir(), "check-plan-renamed"),
    consumer = path.join(root, "consumer"),
    runtime = path.join(root, "runtime");
  const before = browserCheckPlan(release, consumer, runtime, root);
  const original = [...browserChecks];
  const renamed = original.map((_, index) => "scripts/verification/moved-" + index + ".ts");
  const files = new Map(original.map((file, index) => [file, renamed[index]]));
  const entries = browserChecks as unknown as string[];
  try {
    entries.splice(0, entries.length, ...renamed);
    const after = browserCheckPlan(release, consumer, runtime, root);
    expect(after).toEqual(before.map((check) => ({ ...check, file: files.get(check.file)! })));
    expect(after).toHaveLength(24);
  } finally {
    entries.splice(0, entries.length, ...original);
  }
});

