import assert from "node:assert/strict";
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";

const root = "/Users/peterkloss/Dev/ACMElabs/design-system";
const revision = "0a379170fe91a35a0786811d8cff48b9655de5f3";
const baselineFile = path.join(root, "scripts/.workflow-task-01-baseline-" + process.pid + ".ts");
const source = Bun.spawnSync(["git", "show", revision + ":scripts/check.ts"], { cwd: root, stdout: "pipe", stderr: "pipe" });
assert.equal(source.exitCode, 0, source.stderr.toString());
const hash = (value: string) => crypto.createHash("sha256").update(value).digest("hex");
try {
  fs.writeFileSync(baselineFile, source.stdout);
  const baseline = await import(baselineFile);
  const candidate = await import(path.join(root, "scripts/check.ts"));
  const { archiveFilename, releasePackageNames } = await import(path.join(root, "scripts/release-policy.ts"));
  const release = {
    schemaVersion: 2,
    version: "0.3.0",
    commit: "a".repeat(40),
    sourceTree: "clean",
    packages: releasePackageNames.map((name: string) => ({ name, version: "0.3.0", filename: archiveFilename({ name, version: "0.3.0" }), sha512: "a".repeat(128), blockers: [] })),
  };
  const planRoot = "/workflow-migration/check-plan";
  const consumer = path.join(planRoot, "consumer");
  const runtime = path.join(planRoot, "runtime");
  const before = baseline.browserCheckPlan(release, consumer, runtime, planRoot);
  const after = candidate.browserCheckPlan(release, consumer, runtime, planRoot);
  assert.equal(baseline.browserChecks.length, 23);
  assert.equal(candidate.browserChecks.length, 23);
  assert.equal(before.length, 24);
  assert.equal(after.length, 24);
  assert.deepStrictEqual(candidate.browserChecks.map((entry: { file: string }) => entry.file), baseline.browserChecks);
  assert.deepStrictEqual(after, before);
  const encode = (value: unknown) => JSON.parse(JSON.stringify(value, (_, item) => item === undefined ? null : item));
  const record = {
    command: ".artifacts/runtime/bun-1.4.2/bun-darwin-aarch64/bun /private/tmp/workflow-task-01-compare.ts",
    sourceRevision: revision,
    sourceCommand: ["git", "show", revision + ":scripts/check.ts"],
    baselineSourceSha256: hash(source.stdout.toString()),
    candidateSourceSha256: hash(fs.readFileSync(path.join(root, "scripts/check.ts"), "utf8")),
    executionRuntime: { version: Bun.version, executable: process.execPath },
    inputs: { release, root: planRoot, consumer, runtime },
    comparison: { entriesBefore: 23, entriesAfter: 23, invocationsBefore: 24, invocationsAfter: 24, sameOrderedEntryPaths: true, deeplyEqualInvocations: true },
    encoding: "JSON null represents an explicitly undefined environment value; deepStrictEqual compared the original values before serialization.",
    before: encode(before),
    after: encode(after),
    beforeSha256: hash(JSON.stringify(encode(before))),
    afterSha256: hash(JSON.stringify(encode(after))),
    verificationScript: fs.readFileSync(import.meta.path, "utf8"),
  };
  fs.writeFileSync("/private/tmp/workflow-task-01-comparison.json", JSON.stringify(record, null, 2) + "\n");
  console.log(JSON.stringify({ ...record.comparison, beforeSha256: record.beforeSha256, afterSha256: record.afterSha256 }));
} finally {
  fs.rmSync(baselineFile, { force: true });
}
assert.equal(fs.existsSync(baselineFile), false);
console.log("Temporary baseline module removed.");
